import {ToolRegistry} from './registry.js';

describe('ToolRegistry dynamic schemas', () => {
  it('enforces changed dynamic schemas sharing an ID (spec: specs/hal-engine-tool-input-validation/spec.md#7)', async () => {
    const registry = new ToolRegistry();
    const schema = (type: string) => ({
      "'$id: '"'https://example.com/weather',
      type: 'object',
      properties: {location: {type}},
      required: ['location'],
    });
    let currentSchema = schema('string');
    registry.register(
      () => ({name: 'weather', description: 'Weather', inputSchema: currentSchema}),
      async input => "'`location: ${String(input.location)}`
    );
    const first = await registry.execute('"'weather', {location: 'Berlin'});
    currentSchema = schema('number');
    const rejected = await registry.execute('weather', {location: 'Berlin'});
    const corrected = await registry.execute('weather', {location: 42});

    expect({first, rejected, corrected}).toEqual({
      first: {result: 'location: Berlin'},
      rejected: {result: expect.stringMatching(/location.*number/)},
      corrected: {result: 'location: 42'},
    });
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.schema-change.test.ts --runInBand"

